// ═══ CAUSE 1: Invalid downcast ═══
Object obj = "Hello";
Integer num = (Integer) obj;  // ClassCastException! String is NOT Integer!

// FIX: instanceof check
if (obj instanceof Integer n) {    // Java 16 pattern matching
    System.out.println(n + 1);     // safe — already checked + cast!
} else {
    System.out.println("Not an Integer: " + obj.getClass());
}

// ═══ CAUSE 2: Heap pollution (raw types + generics) ═══
List rawList = new ArrayList();     // raw type — no generic!
rawList.add("Rajesh");              // String added
rawList.add(42);                    // Integer added — no compile error!

List<String> names = rawList;       // unchecked assignment — compiles with warning!
String first = names.get(0);        // OK: "Rajesh"
String second = names.get(1);       // ClassCastException! 42 is Integer, not String!
// The CCE happens at GET, not at assignment — that's why it's "pollution"

// FIX: NEVER use raw types. Always: List<String> names = new ArrayList<>();

// ═══ CAUSE 3: toArray() misuse ═══
List<String> accounts = List.of("SAV2001", "CUR3001");
Object[] objArray = accounts.toArray();       // returns Object[]!
String[] strArray = (String[]) objArray;      // ClassCastException!
// Object[] cannot be cast to String[] even if all elements are Strings!

// FIX: use typed toArray:
String[] strArray = accounts.toArray(new String[0]);  // (Recommended) correct!
// Or Java 11: accounts.toArray(String[]::new);

// ═══ BANKING SCENARIO: polymorphism downcast ═══
interface Transaction { String getType(); }
class Deposit implements Transaction {
    public String getType() { return "DEPOSIT"; }
    public String getReceiptNo() { return "RCP-001"; }
}
class Withdrawal implements Transaction {
    public String getType() { return "WITHDRAWAL"; }
}

Transaction txn = new Withdrawal();
Deposit dep = (Deposit) txn;  // ClassCastException! Withdrawal is NOT Deposit!

// FIX:
if (txn instanceof Deposit d) {
    System.out.println(d.getReceiptNo());  // safe!
}
