// ─── File: src/test/java/com/bank/cce/ClassCastTest.java ───
package com.bank.cce;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class ClassCastTest {

    // ═══ INVALID DOWNCAST ═══
    @Test
    void invalidDowncast_throwsCCE() {
        Object obj = "SAV2001";
        assertThatThrownBy(() -> {
            Integer num = (Integer) obj;  // String → Integer: impossible!
        }).isInstanceOf(ClassCastException.class);
    }

    // ═══ instanceof PREVENTS CCE ═══
    @Test
    void instanceofCheck_preventsCCE() {
        Object obj = "SAV2001";
        if (obj instanceof String s) {
            assertThat(s).isEqualTo("SAV2001");  // safe!
        }
        // No CCE — checked before casting!
    }

    // ═══ HEAP POLLUTION ═══
    @Test
    @SuppressWarnings({"unchecked", "rawtypes"})
    void heapPollution_cceAtGet() {
        List rawList = new ArrayList();
        rawList.add("Rajesh");
        rawList.add(42);  // Integer in a "String" list

        List<String> names = rawList;  // unchecked — compiles!

        assertThat(names.get(0)).isEqualTo("Rajesh");  // OK

        assertThatThrownBy(() -> {
            String s = names.get(1);  // CCE! 42 is Integer!
        }).isInstanceOf(ClassCastException.class);
    }

    // ═══ toArray() MISUSE ═══
    @Test
    void toArrayMisuse_throwsCCE() {
        List<String> accounts = List.of("SAV2001", "CUR3001");
        Object[] objArr = accounts.toArray();

        assertThatThrownBy(() -> {
            String[] strArr = (String[]) objArr;  // Object[] → String[]: CCE!
        }).isInstanceOf(ClassCastException.class);
    }

    @Test
    void toArrayCorrect_typedArray() {
        List<String> accounts = List.of("SAV2001", "CUR3001");
        String[] strArr = accounts.toArray(new String[0]);  // (Recommended) correct!
        assertThat(strArr).containsExactly("SAV2001", "CUR3001");
    }

    // ═══ POLYMORPHISM SAFE DOWNCAST ═══
    interface Transaction { String getType(); }
    static class Deposit implements Transaction {
        public String getType() { return "DEPOSIT"; }
        public String receipt() { return "RCP-001"; }
    }
    static class Withdrawal implements Transaction {
        public String getType() { return "WITHDRAWAL"; }
    }

    @Test
    void polymorphism_patternMatching() {
        Transaction txn = new Deposit();
        String result = switch (txn) {
            case Deposit d -> "Deposit receipt: " + d.receipt();
            case Withdrawal w -> "Withdrawal: " + w.getType();
            default -> "Unknown";
        };
        assertThat(result).contains("RCP-001");
    }
}
